const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const lrp=(a,b,t)=>a+(b-a)*t;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsh=(i,j)=>{let h=(i*374761393+j*668265263+P.seed*2246822519)|0; h=((h^(h>>>13))*1274126177)|0; return (h^(h>>>16))>>>0;};

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const st=P.style;
const adobe=st==='adobe', blueprint=st==='blueprint', riso=st==='riso', noir=st==='noir', thermal=st==='thermal';

if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat;
S.lastBeat=K.beat;

let tod=clp(P.tod,0,1);
if(P.act==='cycle'){ tod=clp(0.65-K.section/7*0.6+0.05*Math.sin(K.t*0.05),0,1); }
const night=1-tod;

const bw=Math.round(u*1.15*P.scale), bh=Math.round(u*0.62*P.scale);
const bx0=P.x*W-bw*0.5, by0=P.y*Hh-bh;

const key=bw+'x'+bh+':'+st+':'+P.seed;
if(!S.base||S.key!==key){
  S.key=key; S.win=[];
  const g=createGraphics(bw,bh); g.colorMode(HSB,360,100,100,100); g.noStroke();
  const peakX=bw*0.60, peakY=bh*0.06, leftTopY=bh*0.34, rightTopY=bh*0.52, base=bh;
  const roofY=x=> x<=peakX? lrp(leftTopY,peakY,clp(x/peakX,0,1)) : lrp(peakY,rightTopY,clp((x-peakX)/(bw-peakX),0,1));
  const earth=[[30,32,56],[25,22,70],[35,14,82],[40,28,84],[10,58,58],[15,68,70],[350,50,50],[280,30,46],[42,30,88],[120,24,44],[25,46,34],[0,0,30]];
  function panelCol(idx,brt){
    if(noir){ const v=lrp(24,86,brt); return [220,6,v]; }
    if(thermal){ const h=md(H+lrp(250,40,brt),360); return [h,lrp(85,20,brt),lrp(60,100,brt)]; }
    const c=earth[idx%earth.length]; return [md(c[0]+(H-30),360),c[1],c[2]];
  }
  if(blueprint){ g.background(220,70,26); }
  else{ g.fill(24,20,18); g.beginShape(); for(let x=0;x<=bw;x+=6)g.vertex(x,roofY(x)); g.vertex(bw,base); g.vertex(0,base); g.endShape(g.CLOSE); }
  const cols=16, rows=6, cellW=bw/cols, cellH=(base-leftTopY)/rows;
  for(let i=0;i<cols;i++)for(let j=0;j<rows;j++){
    const px=i*cellW, py=leftTopY+j*cellH, mx=px+cellW*0.5, top=roofY(mx);
    if(py+cellH<top) continue; const dt=Math.max(py,top), hh=(py+cellH)-dt; if(hh<4) continue;
    const hk=hsh(i,j), brt=(hk%100)/100, inset=((hk>>4)&3)*0.5;
    const c=panelCol(hk%earth.length,brt);
    if(blueprint){ g.noFill(); g.stroke(190,50,100,70); g.strokeWeight(Math.max(0.6,bw*0.0009)); g.rect(px+inset,dt,cellW-inset*2,hh-inset); g.noStroke(); continue; }
    if(riso){
      g.fill(200,70,72,55); g.rect(px+inset-1.5,dt-1.5,cellW-inset*2,hh-inset);
      g.fill(8,72,80,55); g.rect(px+inset+1.5,dt+1.5,cellW-inset*2,hh-inset);
      if((hk&3)===0){ g.fill(0,0,100,22); for(let d=0;d<6;d++){ g.ellipse(px+cellW*fr(hk+d),dt+hh*fr(hk*2+d),1.6,1.6);} }
      continue;
    }
    g.fill(c[0],c[1],c[2]); g.rect(px+inset,dt,cellW-inset*2,hh-inset);
    if(adobe){
      g.fill(0,0,0,18); g.rect(px+inset+(cellW-inset*2)*0.6,dt,(cellW-inset*2)*0.4,hh-inset);
      if(c[0]>=25&&c[0]<=45&&(hk&7)<3){ g.stroke(c[0],c[1]+10,Math.max(0,c[2]-18),50); g.strokeWeight(0.5); for(let gg=1;gg<3;gg++){const gy=dt+gg*(hh/3); g.line(px+inset+3,gy,px+cellW-inset-3,gy);} g.noStroke(); }
    }
    if(noir){ g.fill(0,0,0,lrp(6,40,i/cols)); g.rect(px+inset,dt,cellW-inset*2,hh-inset); }
  }
  const doorX=bw*0.50, doorY=leftTopY+cellH*0.7, dW=cellW*0.7, dH=cellH*1.5;
  if(!blueprint){ g.fill(48,74,88); g.rect(doorX,doorY,dW,dH); g.fill(45,88,66); g.rect(doorX+3,doorY+3,dW-6,dH-6); }
  else{ g.noFill(); g.stroke(190,50,100,70); g.rect(doorX,doorY,dW,dH); g.noStroke(); }
  const mx=bw*0.40, my=leftTopY+cellH*0.9, mr=cellH*0.55;
  g.push(); g.translate(mx,my); g.noFill(); g.stroke(blueprint?190:195,60,blueprint?100:78,blueprint?70:100); g.strokeWeight(1.5);
  for(let k=0;k<8;k++){ g.push(); g.rotate(k*Math.PI/4); g.ellipse(0,mr*0.55,mr*0.45,mr*0.95); g.pop(); }
  g.noStroke(); if(!blueprint){ g.fill(48,72,88); g.circle(0,0,mr*0.35); g.fill(15,68,72); g.circle(0,0,mr*0.18);} g.pop();
  const wy=leftTopY+cellH*3.1, wH=cellH*0.95, nW=7;
  for(let k=0;k<nW;k++){ const wx=cellW*(1.2+k*1.9), wW=cellW*0.95; if(wy+wH<roofY(wx+wW*0.5))continue;
    if(blueprint){ g.noFill(); g.stroke(190,50,100,70); g.rect(wx,wy,wW,wH);} else { g.fill(30,30,14); g.rect(wx,wy,wW,wH); g.fill(30,20,8); g.rect(wx+2,wy+2,wW-4,wH-4);} g.noStroke();
    S.win.push({x:wx+wW*0.5,y:wy+wH*0.5,w:wW-4,h:wH-4,lit:fr(k*3+2)<0.72,ph:fr(k*3+3)*6.2832,fk:0.3+fr(k*3+4)});
  }
  if(!blueprint){ for(let i=0;i<Math.round(bw*bh*0.0022);i++){ const px=fr(i*3+9)*bw,py=fr(i*3+8)*bh; if(py<roofY(px))continue; g.fill(0,0,fr(i*3+7)<0.5?100:0,4); g.rect(px,py,1.3,1.3);} }
  S.base=g;
  S.chim={x:bw*0.74,y:roofY(bw*0.74)};
}
image(S.base,bx0,by0,bw,bh);

noStroke();
if(night>0.02){ fill(232,55,14, night*58); rect(bx0,by0,bw,bh); }
if(tod>0.5){ blendMode(ADD); fill(md(H+8,360),40,90, (tod-0.5)*22); rect(bx0,by0,bw,bh); blendMode(BLEND); }

const lightAmt=(0.4+night*0.9)*(0.6+P.energy)+A.lowmid*0.3;
blendMode(ADD); noStroke();
for(let i=0;i<S.win.length;i++){ const wn=S.win[i]; if(!wn.lit)continue;
  const tog=0.5+0.5*Math.sin(K.t*0.35*wn.fk+wn.ph*2);
  const fk=0.6+0.4*Math.sin(K.t*(4+wn.fk*3)*P.speed+wn.ph)+0.15*Math.sin(K.t*11+wn.ph);
  const br=clp(tog*fk,0,1.3)*lightAmt;
  if(br<0.05)continue;
  const wc=blueprint?[190,60,100]:noir?[45,10,100]:thermal?[md(H+30,360),70,100]:[42,80,100];
  const gx=bx0+wn.x, gy=by0+wn.y;
  fill(wc[0],wc[1],wc[2], 55*br); rect(gx-wn.w/2,gy-wn.h/2,wn.w,wn.h);
  fill(wc[0],clp(wc[1]-20,0,100),100, 30*br); ellipse(gx,gy,wn.w*2.4,wn.h*2.4);
}
blendMode(BLEND);

if(S.smokeSeed!==P.seed){ S.smokeSeed=P.seed; S.sm=[]; for(let i=0;i<46;i++)S.sm.push({o:fr(i+5)-0.5,sp:0.4+fr(i+6)*0.8,ph:fr(i+7),sw:0.3+fr(i+8)}); }
const cxp=bx0+S.chim.x, cyp=by0+S.chim.y;
const nS=Math.round(46*clp(P.density,0.15,1));
const plumeH=u*0.4*P.scale*(0.5+P.energy);
noStroke();
for(let i=0;i<nS;i++){ const s2=S.sm[i];
  const life=frc(s2.ph+K.t*0.06*s2.sp*P.speed);
  const sx=cxp+s2.o*u*0.02+Math.sin(K.t*0.7*s2.sw+i)*u*0.04*life;
  const sy=cyp-life*plumeH;
  const sz=u*0.01*(0.5+life*1.6)*(0.5+s2.sw);
  const a=(1-life)*(0.12+night*0.14)*(thermal?2.2:1)*(0.4+P.decay);
  const sc2= thermal?[md(H+lrp(30,240,life),360),60,90] : blueprint?[200,20,80] : [30,10,lrp(60,88,tod)];
  fill(sc2[0],sc2[1],sc2[2], a*100); ellipse(sx,sy,sz,sz*1.1);
}

blendMode(ADD); noStroke();
const nd=Math.round(26*clp(P.density,0.2,1));
for(let i=0;i<nd;i++){ const dx=frc(fr(i+50)+K.t*0.02*(0.5+fr(i+51)))*bw, dy=fr(i+52)*bh*0.4+bh*0.55;
  const tw=0.5+0.5*Math.sin(K.t*(1.5+fr(i+53))+i);
  fill(md(H+10,360),25,100, (0.06+tod*0.06)*tw*100*P.decay); ellipse(bx0+dx,by0+dy+Math.sin(K.t*0.9+i)*u*0.01,u*0.003,u*0.003);
}
blendMode(BLEND);
